// The almanac's events, July to December 1899 (Core/Almanac.cs has the logic; AlmanacData1899A.cs the first half and the
// shape of an entry).
namespace EnrageWestworld.Core
{
    public static partial class Almanac
    {
        private static readonly AlmanacEvent[] Events1899B =
        {
            // ---- July 1899 -------------------------------------------------------------------------------------
            E("omahaexpo", 1899, 7, 1, "west", 1, "west", "OMAHA OPENS ANOTHER EXPOSITION",
              "Omaha has opened a Greater America Exposition on last year's grounds, with the new islands as the show this time.",
              "Omaha's got another fair going. Last year's buildings, this year's islands. Filipinos on show, like a zoo.",
              "The Omaha fair's showing the new islands. Huts, natives and a battleship model. I'd go for the lemonade."),
            E("dreyfushome", 1899, 7, 2, "world", 1, "world", "DREYFUS LANDS IN FRANCE",
              "Captain Dreyfus was landed by night on the coast of Brittany after four years on Devil's Island, thin and gray, and taken to the prison at Rennes.",
              "Dreyfus is back in France after four years on Devil's Island. They say his hair went white at thirty-nine.",
              "They landed Dreyfus at night like a smuggler, for fear of the crowds. France is two countries over one man."),
            E("brazosflood", 1899, 7, 3, "south", 3, "disaster", "THE BRAZOS OUT OF ITS BANKS FOR A HUNDRED MILES",
              "The Brazos River in Texas has drowned the bottom lands from Waco toward the Gulf, with hundreds dead and the cotton country under water.",
              "The Brazos has drowned half of Texas. Hundreds dead in the bottoms. A man rowed over the roofs of a town.",
              "The Texas flood. The cotton country's under water from Waco down. They'll be eating the mules by August.",
              "The Brazos took the bottoms and everybody in them. Weeks of rain, and it all came down the one river."),
            E("juvenilecourt", 1899, 7, 4, null, 1, "law", "THE FIRST CHILDREN'S COURT SITS AT CHICAGO",
              "The children's court opened at Chicago, the first in the world, and heard its first boy with no cell or chain in sight.",
              "The children's court opened in Chicago. First one anywhere. A judge for boys, and no bars on the windows.",
              "Chicago tries children in their own court now. Soft, some say. A boy jailed with thieves learns the trade."),
            E("folsomrobbery", 1899, 7, 12, "west", 2, "crime", "THE COLORADO AND SOUTHERN HELD UP AT FOLSOM",
              "Three men stopped the Colorado and Southern train near Folsom, New Mexico, blew open the express car and got away into the canyons.",
              "Train robbed at Folsom, New Mexico. Ketchum's bunch, they think. Blew the express car and took to the hills.",
              "Another express car dynamited, at Folsom this time. Two trains in six weeks. They'll ride with cannon soon."),
            E("turkeycreek", 1899, 7, 17, "west", 2, "crime", "SHERIFF FARR KILLED FIGHTING THE FOLSOM ROBBERS",
              "A posse came on the Folsom robbers in Turkey Creek Canyon, and in the fight Sheriff Farr of Huerfano County was killed and two of the robbers hit.",
              "They cornered the Folsom robbers in Turkey Creek Canyon. Sheriff Farr killed, two of the gang shot.",
              "Another sheriff dead after train robbers. Farr, of Colorado. Those canyons favor the man who's waiting."),
            E("alger", 1899, 7, 19, null, 1, "death", "HORATIO ALGER DEAD",
              "Horatio Alger, whose hundred books took a generation of poor boys from rags to riches by pluck and luck, has died in Massachusetts.",
              "Horatio Alger's dead. All those books where the newsboy ends up a banker. Never happened to one I knew.",
              "Horatio Alger died. Read every book of his at twelve. Pluck and luck. I've had the pluck."),
            E("newsboys", 1899, 7, 21, null, 2, "life", "THE NEWSBOYS STRIKE AGAINST THE BIG PAPERS",
              "The newsboys of New York have struck against Mr. Pulitzer's World and Mr. Hearst's Journal over the price of a bundle, and the sales have fallen by half.",
              "The New York newsboys are striking against Hearst and Pulitzer. Little fellows of ten. And they're winning.",
              "The newsboys shut down the yellow papers. Pulitzer can buy a senator, but not a ten-year-old with a bundle."),
            E("ingersoll", 1899, 7, 22, null, 2, "death", "COLONEL INGERSOLL, THE GREAT AGNOSTIC, DEAD",
              "Robert Ingersoll, who filled halls for thirty years arguing against the churches, died suddenly at Dobbs Ferry, New York.",
              "Ingersoll died, the infidel lecturer. Every preacher in the country has a sermon ready on where he went.",
              "Bob Ingersoll's dead. Heard him once. Didn't agree with a word and couldn't stop listening. He could talk."),
            E("cocacolabottle", 1899, 7, 25, "south", 1, "life", "COCA-COLA TO BE SOLD IN BOTTLES",
              "Two Chattanooga men have bought the right to put the Atlanta soda fountain drink, Coca-Cola, in bottles and sell it anywhere.",
              "That Atlanta drink, Coca-Cola, is going in bottles. Drink it in the field instead of at the fountain.",
              "Coca-Cola in a bottle, five cents. Tastes like medicine and I've had three today."),
            E("samketchum", 1899, 7, 26, "west", 1, "crime", "SAM KETCHUM DEAD IN THE PENITENTIARY",
              "Sam Ketchum, shot through the arm in the Turkey Creek fight, has died of the poisoned wound in the penitentiary at Santa Fe.",
              "Sam Ketchum died in the Santa Fe pen. Blood poison from the Turkey Creek wound. Train robbing's a short trade.",
              "One of the Ketchum brothers is dead of a bullet in the arm. A bullet in the arm. That's how it goes in a cell."),
            E("hagueclose", 1899, 7, 31, "world", 1, "world", "THE PEACE CONFERENCE SIGNS ITS PAPERS",
              "The Hague conference has ended with a court for nations to take their quarrels to, and rules against poison gas and bombs dropped from balloons.",
              "The Hague peace conference is over. A court for nations to argue in, and no bombs from balloons.",
              "They signed the peace papers at The Hague. A court for countries. I'll believe it when a king's in the dock."),
            E("newvolunteers", 1899, 7, 10, null, 2, "war", "NEW REGIMENTS RECRUITING FOR THE ISLANDS",
              "The War Department is raising its new volunteer regiments for the Philippines, and recruiting offices have opened in every city of the West.",
              "Recruiting sergeant in town for the Philippines. Thirteen dollars a month. Three boys from here signed.",
              "The new regiments for the islands are filling fast. Young fellows with no work and a taste for the band."),
            // ---- August 1899 -----------------------------------------------------------------------------------
            E("rennes", 1899, 8, 8, "world", 2, "world", "DREYFUS BEFORE THE COURT AT RENNES",
              "The new court-martial of Captain Dreyfus opened at Rennes before the correspondents of every paper in the world.",
              "The Dreyfus trial's started again in France, at Rennes. More reporters there than soldiers, they say.",
              "They're trying Dreyfus a second time. Same generals, same lies, the paper says. France can't let it go."),
            E("sanciriaco", 1899, 8, 10, "south", 3, "disaster", "A HURRICANE LAYS PORTO RICO WASTE",
              "A hurricane crossed Porto Rico from end to end and left thousands dead and the island's coffee crop gone; the army is feeding the people.",
              "A hurricane went through Porto Rico. Thousands dead. Our island now, so it's our soldiers handing out bread.",
              "Porto Rico's wrecked by the hurricane. Coffee's gone, houses gone. A year ours, and it costs us a hurricane."),
            E("laborishot", 1899, 8, 15, "world", 1, "crime", "DREYFUS'S LAWYER SHOT IN THE STREET",
              "Maitre Labori, counsel for Dreyfus, was shot in the back on his way to court at Rennes by a man who got away; the lawyer lives.",
              "Somebody shot Dreyfus's lawyer on his way to court. In the back. That's how they argue law in France now.",
              "They shot the Dreyfus lawyer. Not the captain, the lawyer. And the man got away. Bad year to be a Frenchman."),
            E("blackjack", 1899, 8, 17, "west", 2, "crime", "BLACK JACK KETCHUM TRIES THE FOLSOM TRAIN ALONE",
              "Tom Ketchum, Black Jack, held up the Folsom train single-handed, was shot through the arm by the conductor and was found the next morning by the track.",
              "Black Jack Ketchum tried to rob a train alone. The conductor shot him, and they found him by the track.",
              "The last Ketchum's caught. Held up a train alone and the trainmen shot him off it. New Mexico will hang him."),
            E("elzylay", 1899, 8, 18, "west", 1, "crime", "ONE OF THE FOLSOM ROBBERS TAKEN",
              "A posse near Carlsbad caught Elza Lay, wanted for the Folsom robbery and Sheriff Farr's death, after a fight in which he was wounded.",
              "They caught Elza Lay down by Carlsbad. Hole-in-the-Wall man, wanted for Folsom. The gang's coming apart.",
              "Another train robber in irons, Lay this time. New Mexico's filling its jails with them this summer."),
            E("hatterasstorm", 1899, 8, 19, "south", 2, "disaster", "THE HURRICANE STRIKES HATTERAS",
              "The hurricane that wrecked Porto Rico came up the coast and struck Hatteras and the Carolina sounds, drowning villages and sinking ships.",
              "The Porto Rico hurricane came up and hit the Carolinas. Hatteras under water, ships lost on the banks.",
              "That hurricane's been a week on the map. Porto Rico, then the Carolinas. A storm with a railroad schedule."),
            E("nomebeach", 1899, 8, 20, "high", 3, "west", "GOLD IN THE BEACH SAND AT NOME",
              "The beaches at Nome on the Bering Sea are gold-bearing for miles, and men are washing it out of the sand with rockers at the water's edge.",
              "They're finding gold in the beach sand at Nome. Scoop it up and wash it. Every boat out of Seattle's full.",
              "Gold on the beach at Nome, no digging. Half the Klondike's going. I'd go myself if it wasn't the Arctic.",
              "There's gold lying on a beach in Alaska and I'm here shoeing horses. Tell me again why."),
            E("nebraskanshome", 1899, 8, 25, "west", 2, "war", "THE FIRST NEBRASKA HOME FROM MANILA",
              "The First Nebraska was mustered out at San Francisco and came home to Lincoln and Omaha to parades, with its colonel dead and many of its men sick.",
              "The Nebraska boys are home. Paraded through Lincoln with the flag from Manila. Half of them yellow with fever.",
              "The First Nebraska's back from the islands. Bryan met them at the depot with a speech. He would."),
            // ---- September 1899 --------------------------------------------------------------------------------
            E("opendoor", 1899, 9, 7, null, 1, "world", "SECRETARY HAY WRITES THE POWERS ON CHINA",
              "Secretary Hay has written to the great powers asking that the door of China be kept open to the trade of every nation.",
              "Secretary Hay's written the kings about China. Keep the door open for trade, he says. Open for us, he means.",
              "The Open Door, Hay calls it. We want to sell in China before the English and the Russians lock it up."),
            E("frontierdays", 1899, 9, 0, "west", 1, "west", "FRONTIER DAYS AT CHEYENNE",
              "Cheyenne has held its Frontier Days again, with bucking contests and wild horse races, and cowmen in from every ranch within a hundred miles.",
              "Frontier Days at Cheyenne. Bronc riding and a wild horse race down main street. Three days, nobody sober.",
              "Cheyenne's made a show of ranch work, Frontier Days. Pay to watch a man do what I do for wages."),
            E("dreyfusverdict", 1899, 9, 10, "world", 2, "world", "DREYFUS GUILTY AGAIN",
              "The court at Rennes found Captain Dreyfus guilty a second time, five votes to two, with extenuating circumstances, and gave him ten years.",
              "Dreyfus guilty again. Extenuating circumstances, whatever those are for treason. The world laughs at France.",
              "Dreyfus found guilty a second time. Ten years. Folks are saying boycott the Paris fair over one captain."),
            E("bliss", 1899, 9, 15, null, 2, "life", "THE FIRST MAN KILLED BY A HORSELESS CARRIAGE",
              "A Mr. Bliss stepping off a streetcar in New York was struck by an electric cab and died the next morning, the first death of its kind.",
              "A horseless carriage killed a man in New York, stepping off a streetcar. The first, they say. Not the last.",
              "An electric cab killed a man on Central Park West. A horse would have stopped. A horse has sense."),
            E("phillyexpo", 1899, 9, 15, null, 1, "money", "AN EXPORT EXPOSITION AT PHILADELPHIA",
              "Philadelphia has opened a National Export Exposition to show the world what American factories make, with buyers come from every country.",
              "A fair at Philadelphia for selling American goods abroad. We used to buy from them. Now they buy from us.",
              "An export exposition at Philadelphia. Means we make more than we can use. That's new for this country."),
            E("transvaalcrisis", 1899, 9, 15, "world", 2, "world", "WAR CLOUDS OVER THE TRANSVAAL",
              "England is sending troops to South Africa and the Boers are buying rifles; the papers give it a month before the shooting starts.",
              "England's sending soldiers to Africa against the Boers. Farmers against an empire. A month, the paper says.",
              "Boers and British about to fight over the Transvaal gold. London says it'll be over by Christmas."),
            E("coloradoshome", 1899, 9, 18, "high", 2, "war", "THE FIRST COLORADO HOME",
              "The First Colorado came home from the Philippines through Denver to a parade down Sixteenth Street, with the city shut for the day.",
              "The Colorado boys came home through Denver. Whole city out, the paper says. The mines shut to see them.",
              "First Colorado's back from Manila, thin as rails. The band played and the mothers counted faces."),
            E("dreyfuspardon", 1899, 9, 20, "world", 1, "world", "DREYFUS PARDONED",
              "The President of France has pardoned Captain Dreyfus, who took it to save his life and says he will go on seeking his honor.",
              "They pardoned Dreyfus. Not cleared, pardoned. Guilty and free. France found the way to please nobody.",
              "Dreyfus is out, pardoned. Ten days ago they gave him ten years. I can't follow it and I doubt they can."),
            E("mapleleaf", 1899, 9, 20, "west", 2, "life", "A NEW RAG FROM SEDALIA",
              "A Sedalia, Missouri, pianist named Joplin has a piece out called the Maple Leaf Rag, printed by Mr. Stark of that town.",
              "There's a new rag out of Sedalia, the Maple Leaf. The saloon fellow plays it till the keys smoke.",
              "That Maple Leaf Rag. The church ladies say it's the devil's own and hum it on the way home."),
            E("wyattnome", 1899, 9, 20, "west", 1, "west", "WYATT EARP GONE TO NOME",
              "Wyatt Earp of the Tombstone fight has gone to Nome with his wife to open a saloon on the beach where the gold is.",
              "Wyatt Earp's gone to Nome to run a saloon. Tombstone Wyatt. He goes where the money is, and it's in the sand.",
              "Earp in Alaska with a saloon on the beach. The men who made the West sell drinks to the men digging the rest."),
            E("deweyhome", 1899, 9, 27, null, 3, "world", "DEWEY COMES HOME",
              "The Olympia came in past Sandy Hook with Admiral Dewey on the bridge, and New York has built him an arch of white plaster and planned two days of parades.",
              "Dewey's home. New York's gone crazy. Built an arch across Fifth Avenue for him like a Roman emperor.",
              "Admiral Dewey landed at New York. Two days of parades, and every ship in the harbor blowing its whistle.",
              "Dewey's back from Manila. They're talking of him for president. He's never said a word about politics."),
            // ---- October 1899 ----------------------------------------------------------------------------------
            E("deweysword", 1899, 10, 4, null, 1, "world", "CONGRESS GIVES DEWEY HIS SWORD",
              "The Admiral was given the gold sword voted him by Congress on the steps of the Capitol, with the President by and fifty thousand looking on.",
              "They gave Dewey a gold sword at Washington, McKinley looking on. A sword, for a man who fought with cannon.",
              "Dewey got his sword from Congress. I'd have taken the money. He's got a house too, that the people bought."),
            E("mountainplain", 1899, 10, 5, "high", 1, "west", "DENVER'S FESTIVAL OF MOUNTAIN AND PLAIN",
              "Denver held its Festival of Mountain and Plain, with the Slaves of the Silver Serpent parading at night and every camp in the state sending a float.",
              "Denver's festival is on, Mountain and Plain. The silver serpent parade at night with torches. Worth the fare.",
              "The Denver festival. Floats, cowboys and a parade of miners. The whole state goes down to look at itself."),
            E("boerwar", 1899, 10, 12, "world", 3, "war", "WAR IN SOUTH AFRICA",
              "President Kruger's ultimatum ran out, and the Boer commandos crossed into Natal; the British Empire is at war with two republics of farmers.",
              "It's war in Africa. The Boers rode into Natal the day the ultimatum ran out. Farmers against the British army.",
              "The Boers have gone to war with England. Every Boer can shoot a buck at four hundred yards, they say.",
              "The English and the Dutch farmers are at it in Africa. The farmers for the first year, the empire the last."),
            E("kansanshome", 1899, 10, 12, "west", 2, "war", "FUNSTON AND THE TWENTIETH KANSAS HOME",
              "The Twentieth Kansas, Funston's regiment, has landed at San Francisco from Manila, and Kansas is planning the biggest day Topeka ever saw.",
              "Funston's Kansans are home from Manila. The little colonel who crossed the river under fire. Topeka's ready.",
              "The Twentieth Kansas is back from the islands. Funston's a general now. Five foot four and afraid of nothing."),
            E("brooklynpennant", 1899, 10, 16, null, 1, "sport", "BROOKLYN TAKES THE PENNANT, CLEVELAND THE CELLAR",
              "Brooklyn has the National League pennant, and Cleveland, stripped of its best players for St. Louis, won twenty games and lost a hundred and thirty-four.",
              "Brooklyn won the pennant. And Cleveland lost a hundred and thirty-four games. Nobody came to watch.",
              "The Cleveland owners sold every ball player worth a nickel to St. Louis. Twenty wins all season."),
            E("kimberley", 1899, 10, 17, "world", 1, "war", "KIMBERLEY AND MAFEKING SHUT IN",
              "The Boers have closed round Kimberley, with Cecil Rhodes and his diamond mines inside, and round Mafeking, where Colonel Baden-Powell holds the town.",
              "The Boers have Cecil Rhodes shut up in Kimberley with his diamonds. Can't say I'm sorry for him.",
              "Mafeking's surrounded, and Kimberley. The Boers hold the country and the English hold the towns."),
            E("americascup", 1899, 10, 21, null, 2, "sport", "COLUMBIA KEEPS THE CUP",
              "The yacht Columbia beat Sir Thomas Lipton's Shamrock three races straight off Sandy Hook, and the America's Cup stays where it has been since 1851.",
              "Columbia beat the Englishman's boat three straight. Lipton, the tea fellow. He took it well and sold tea.",
              "The yacht race is over. Our boat, three to nothing. The English have chased that cup since 1851."),
            E("marconiraces", 1899, 10, 21, null, 1, "wonder", "THE YACHT RACES REPORTED WITHOUT WIRES",
              "Marconi came over to report the yacht races for a New York paper by his wireless telegraph from a ship on the course, and the news beat the boats to shore.",
              "They telegraphed the yacht races from a boat with no wire. The paper had the result before the boats were in.",
              "Marconi sent the yacht race results through the air to shore. If that works, ships at sea can call home."),
            E("alaskaboundary", 1899, 10, 22, "high", 1, "world", "A LINE DRAWN IN ALASKA FOR NOW",
              "Washington and London have agreed on a line for now between Alaska and Canada where the Lynn Canal ends, so the gold trails can be policed.",
              "They've drawn a line between Alaska and Canada for now. Nobody knew where it was with the gold going over.",
              "The Alaska line's settled for the winter. Mounties one side, our men the other, and the miners not caring."),
            E("ladysmith", 1899, 10, 31, "world", 2, "war", "THE BRITISH DRIVEN INTO LADYSMITH",
              "The Boers beat the British outside Ladysmith and took a thousand prisoners on a hill, and the town is all but surrounded.",
              "The Boers whipped the British at Ladysmith and took a thousand prisoners. Mournful Monday, London calls it.",
              "The British are shut up in Ladysmith by farmers in slouch hats. The empire doesn't look so big this week."),
            // ---- November 1899 ---------------------------------------------------------------------------------
            E("jeffriessharkey", 1899, 11, 4, null, 2, "sport", "JEFFRIES BEATS SHARKEY IN TWENTY-FIVE ROUNDS",
              "Jeffries kept his title against Tom Sharkey at Coney Island in twenty-five rounds under four hundred electric lamps set up to take the pictures.",
              "Jeffries and Sharkey went twenty-five rounds under electric lights so they could take pictures of it.",
              "Twenty-five rounds. Sharkey's ribs broke and he never went down. The lights near cooked them both."),
            E("sherlockplay", 1899, 11, 7, null, 1, "life", "SHERLOCK HOLMES ON THE STAGE",
              "Mr. Gillette has made a play of Sherlock Holmes and plays the detective himself in New York, pipe, dressing gown and all.",
              "They've put Sherlock Holmes on the stage in New York, Gillette playing him. My wife wants to go East for it.",
              "A Sherlock Holmes play. I've read every one of those stories. I'd pay to watch the man think out loud."),
            E("electionday99", 1899, 11, 8, null, 2, "politics", "THE OFF-YEAR ELECTIONS",
              "The Republicans held Ohio, and in Kentucky Goebel and Taylor each claim the governorship and both sides are arming.",
              "Election's over. Ohio went Republican and Kentucky's fighting over who won governor. Both sides have rifles.",
              "Kentucky's got two governors and both of them armed. That's not an election, that's a feud with ballots."),
            E("deweywedding", 1899, 11, 10, null, 2, "life", "ADMIRAL DEWEY MARRIES, AND GIVES AWAY HIS HOUSE",
              "The Admiral married Mrs. Hazen quietly at Washington and deeded her the house the people's dimes bought him; the people are not pleased.",
              "Dewey married and gave his new wife the house the country bought him. Folks who sent a dime are raging.",
              "The Admiral's married a widow and signed her the house we all paid for. Two months ago he was a king."),
            E("aguinaldoguerrilla", 1899, 11, 15, null, 2, "war", "AGUINALDO'S ARMY BREAKS UP",
              "Aguinaldo has broken up his army and gone into the mountains, the generals say, and the war in the islands will be fought by small bands from now on.",
              "Aguinaldo's army's broke up. He's gone into the mountains. The generals say it's won. The boys' letters don't.",
              "The Filipinos quit fighting like an army. Bands in the hills now. That kind of war doesn't end, my uncle says."),
            E("leonids", 1899, 11, 16, null, 2, "wonder", "THE GREAT METEOR SHOWER FAILS TO COME",
              "The astronomers promised the Leonids would fill the sky as they did in 1833, and half the country sat up till dawn in the cold to see a dozen stars fall.",
              "Sat up all night for the meteor shower the professors promised. Saw six. The whole town in blankets for six.",
              "The shooting stars never came. The astronomers had the whole country up till dawn. They'll blame the clouds."),
            E("churchillcaptured", 1899, 11, 17, "world", 1, "war", "AN ARMORED TRAIN WRECKED BY THE BOERS",
              "The Boers wrecked a British armored train near Ladysmith and took a London correspondent, a young Churchill, prisoner with the soldiers.",
              "The Boers wrecked an armored train and caught a newspaperman with the soldiers. Churchill, some lord's son.",
              "A reporter taken prisoner in Africa with the troops. The papers send boys where the generals won't go."),
            E("harvardyale", 1899, 11, 20, null, 1, "sport", "HARVARD AND YALE PLAY TO NOTHING",
              "Harvard and Yale played their football game before thirty thousand, and neither side could score.",
              "Harvard and Yale played football to no score. Thirty thousand people paid to watch nobody win.",
              "The college boys played their big game and it came out nothing to nothing. Broken noses for that."),
            E("dooleycubia", 1899, 11, 20, null, 1, "politics", "MR. DOOLEY ON COLONEL ROOSEVELT'S BOOK",
              "Mr. Dooley, the saloon philosopher of the Chicago paper, has reviewed Governor Roosevelt's book of the war and says it should be called Alone in Cuba.",
              "Mr. Dooley says Teddy's war book ought to be called Alone in Cuba. Teddy wrote that he laughed. He'd better.",
              "Dooley on Teddy's Rough Riders book. Alone in Cubia. I read it twice. The Irishman says what we only think."),
            E("pearlharttrial", 1899, 11, 20, "west", 1, "crime", "PEARL HART BEFORE A JURY",
              "The Arizona jury let the woman stage robber go, the judge called them fools and tried her again on another charge, and she has five years at Yuma.",
              "The jury turned Pearl Hart loose. The judge swore at them and tried her again. Five years at Yuma now.",
              "Twelve Arizona men and not one would send Pearl Hart to Yuma. Took the judge a second try."),
            E("hobartdead", 1899, 11, 22, null, 3, "death", "VICE PRESIDENT HOBART DEAD",
              "Vice President Hobart died at his home in Paterson after a long illness of the heart, and who runs with McKinley next year is an open question.",
              "The Vice President's dead. Hobart. Heart gave out. Every man in Washington wants his place on the ticket now.",
              "Hobart died. Nobody knew his name a week ago; now the paper's full of who runs with McKinley. Teddy, some say.",
              "Vice President Hobart's gone. A heartbeat from the White House, they say of that office. His quit first."),
            E("benhur", 1899, 11, 30, null, 2, "life", "BEN-HUR ON THE STAGE WITH REAL HORSES",
              "The play of Ben-Hur opened at New York with the chariot race run by live horses on treadmills before a painted circus, and the house rose to its feet.",
              "Ben-Hur's on the stage in New York with real horses running the chariot race on a machine. The crowd stood up.",
              "Ben-Hur's chariot race with living horses on treadmills. How do they keep them out of the scenery?"),
            // ---- December 1899 ---------------------------------------------------------------------------------
            E("samoatreaty", 1899, 12, 4, "world", 1, "world", "SAMOA DIVIDED",
              "The United States, England and Germany have divided the Samoan islands; we keep the harbor at Pago Pago and the Germans the rest.",
              "They carved up Samoa. We get the harbor at Pago Pago, the Germans the rest. The Samoans get told.",
              "Samoa's settled. Three countries drew a line through somebody else's islands. That's how it's done now."),
            E("sixdayrace", 1899, 12, 5, null, 1, "sport", "THE SIX-DAY BICYCLE RACE",
              "The six-day bicycle race is on at Madison Square Garden, teams of two riding day and night round a board track with the crowd betting on every lap.",
              "There's a bicycle race in New York that goes six days without stopping. Men fall asleep on the wheel.",
              "Six-day race at the Garden. Two thousand miles in a circle, and people pay to watch it."),
            E("robertsutah", 1899, 12, 5, "high", 2, "politics", "CONGRESS TAKES UP THE CASE OF ROBERTS OF UTAH",
              "The House will not seat Brigham Roberts of Utah, elected with three wives, and the petitions against him are said to carry seven million names.",
              "Congress won't seat that Utah man with three wives. Roberts. Seven million signed against him. He was elected.",
              "They're keeping the Mormon out of Congress. Utah's a state four years and still treated like a territory."),
            E("tiradpass", 1899, 12, 6, null, 1, "war", "THE BOY GENERAL KILLED AT TIRAD PASS",
              "General del Pilar, twenty-four years old, held Tirad Pass against our troops with sixty men to let Aguinaldo escape, and died there with most of them.",
              "A Filipino general of twenty-four held a mountain pass with sixty men so Aguinaldo could get away. Died there.",
              "Del Pilar, the boy general, died holding Tirad Pass. Our boys say he fought like a Texan."),
            E("blackweek", 1899, 12, 17, "world", 3, "war", "THE BRITISH BEATEN THREE TIMES IN A WEEK",
              "The Boers have beaten the British at Stormberg, Magersfontein and Colenso inside a week, and London calls it the black week of the empire.",
              "The Boers beat the British three times in one week. Black week, England calls it. Farmers, against the empire.",
              "At Magersfontein the Boers lay in trenches and the British walked into them in rows. The old way's dead.",
              "The empire's lost three battles in a week to men who farm. Not a man in the territory isn't a little pleased."),
            E("robertscommand", 1899, 12, 19, "world", 1, "war", "LORD ROBERTS SENT TO SOUTH AFRICA",
              "London has sent Lord Roberts to command in South Africa in Buller's place, in the same week his only son died of wounds at Colenso.",
              "England's sending old Lord Roberts to take over in Africa. His only son died at Colenso this week.",
              "They've put Roberts over Buller in Africa. An old man with a dead son going to fight farmers. Sad business."),
            E("goldbill", 1899, 12, 19, null, 2, "money", "THE HOUSE PASSES THE GOLD BILL",
              "The House has passed the bill to make gold the one standard of the country's money, and the silver men say the Senate will hear from the West.",
              "The House passed the gold bill. Gold's the money now, or will be. The silver men are hollering in Denver.",
              "Gold standard by law, near enough. The House voted it. Bryan will make a year of speeches out of that."),
            E("lawtonkilled", 1899, 12, 21, null, 3, "death", "GENERAL LAWTON KILLED IN THE PHILIPPINES",
              "General Lawton, who ran down Geronimo and led the advance at Santiago, was shot dead at San Mateo standing in the open in his white helmet.",
              "General Lawton's killed in the islands. Stood in the open in that white helmet, and a sharpshooter got him.",
              "Lawton's dead, the man who ran down Geronimo. Shot at San Mateo. The whole army's in black for him.",
              "General Lawton killed. Tall as a door and he'd not duck for any bullet. The paper says the whole line wept."),
            E("woodcuba", 1899, 12, 21, null, 1, "world", "GENERAL WOOD TO GOVERN CUBA",
              "General Leonard Wood, the Rough Riders' first colonel and the man who cleaned up Santiago, is military governor of all Cuba.",
              "Leonard Wood's governor of Cuba now, the doctor who led the Rough Riders. He cleaned up Santiago.",
              "A surgeon with a general's stars runs Cuba. Everything comes back to that Rough Rider regiment."),
            E("moodydead", 1899, 12, 23, null, 3, "death", "DWIGHT MOODY, THE EVANGELIST, DEAD",
              "Dwight L. Moody, who preached to more people than any man living, died at his home at Northfield after breaking down on a tour in Kansas City.",
              "Moody's dead, the evangelist. Broke down preaching in Kansas City and went home to Northfield to die.",
              "Moody died. I heard him in a tent when I was a boy. Ten thousand people and not a sound but his voice.",
              "The great preacher Moody's gone. Moody and Sankey. The hymns will outlive us all, the preacher says."),
            E("honoluluplague", 1899, 12, 15, "world", 1, "disaster", "THE PLAGUE AT HONOLULU",
              "The plague has broken out in the Chinese quarter of Honolulu, in our new islands, and the board of health has shut the quarter in.",
              "The plague's in Honolulu. The real plague, the black death. They've shut the Chinese quarter in.",
              "Bubonic plague in Hawaii, our territory now. Came on a ship from China. Ships bring everything, in the end."),
            E("britishmules", 1899, 12, 10, "south", 2, "money", "THE BRITISH BUYING MULES AT NEW ORLEANS",
              "British army buyers at New Orleans are taking every sound mule and horse offered, at prices not seen in years, to ship to the war in South Africa.",
              "The English are buying mules at New Orleans for the Boer war. Any price. A string of mules is a fortune.",
              "British agents at the stockyards buying horses for Africa, paying gold. My mules never looked so fine."),
            E("centuryend", 1899, 12, 31, null, 2, "life", "THE LAST NIGHT OF THE CENTURY, OR IS IT",
              "Half the papers say the century ends tonight and the other half say it has a year to run, and the mathematicians have been no help at all.",
              "End of the century tonight, or it isn't. Preacher says next year, the paper says tonight. I'll drink to both.",
              "Last night of the century, they say in the saloon. The schoolmaster says next year. Nobody's listening to him.",
              "Nineteen hundred tomorrow. New century or not, it's a new number, and that's enough for me.")
        };
    }
}
